   $$economie-havo-2017-ii-china-grijpt-in-vraag12.png$$, $$1p 12 Bereken met hoeveel yuan de koers van de dollar (uitgedrukt in yuan) in de maand augustus 2015 is veranderd.$$, array['a4701e34-2c0a-4882-a5d2-d415e4acc330']::uuid[]),
