   $$economie-havo-2017-ii-china-grijpt-in-vraag15.png$$, $$2p 15 Leg uit dat de koersdaling van de yuan via de lopende rekening van de betalingsbalans kan leiden tot meer economische groei in China.$$, array['a4701e34-2c0a-4882-a5d2-d415e4acc330']::uuid[]),
